from __future__ import annotations

from pathlib import Path
from unittest.mock import MagicMock

import pytest

from olf.common.deployment.errors import DeploymentError, DeploymentPreconditionError
from olf.common.deployment.project_dependencies import check_project_requirements, platform_constraints

LOCK = """\
# This file was autogenerated by uv
agate==1.9.1 \\
    --hash=sha256:aa \\
    --hash=sha256:bb
    # via dbt-core
numpy==2.0.0 ; python_version >= '3.9' \\
    --hash=sha256:cc
"""


def test_platform_constraints_keep_only_pins() -> None:
    assert platform_constraints(LOCK) == "agate==1.9.1\nnumpy==2.0.0 ; python_version >= '3.9'\n"


def _project(tmp_path: Path) -> tuple[Path, Path]:
    requirements = tmp_path / "requirements.txt"
    requirements.write_text("numpy==1.0\n")
    lock = tmp_path / "requirements.lock"
    lock.write_text(LOCK)
    return requirements, lock


def test_check_compiles_against_the_platform_pins(tmp_path: Path) -> None:
    requirements, lock = _project(tmp_path)
    tools = MagicMock()
    tools.resolver.resolve.return_value = "uv"

    check_project_requirements(requirements, lock, tools=tools)

    argv = tools.runner.run.call_args.args[0]
    assert argv[:4] == ["uv", "pip", "compile", str(requirements)]
    assert "--constraint" in argv


def test_conflict_with_the_platform_pins_is_a_clear_error(tmp_path: Path) -> None:
    requirements, lock = _project(tmp_path)
    tools = MagicMock()
    tools.resolver.resolve.return_value = "uv"
    tools.runner.run.side_effect = DeploymentError("numpy==1.0 conflicts with numpy==2.0.0")

    with pytest.raises(DeploymentPreconditionError, match="conflicts with the platform dependency pins"):
        check_project_requirements(requirements, lock, tools=tools)
